// Order-18 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny feedback stage -> critical path roughly
// independent of the order -> high Fmax. Same function as the direct form.
module iir18_v7 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] r4;
  reg [15:0] r5;
  reg [15:0] r6;
  reg [15:0] r7;
  reg [15:0] r8;
  reg [15:0] r9;
  reg [15:0] r10;
  reg [15:0] r11;
  reg [15:0] r12;
  reg [15:0] r13;
  reg [15:0] r14;
  reg [15:0] r15;
  reg [15:0] r16;
  reg [15:0] r17;
  reg [15:0] r18;
  reg [15:0] fb;
  wire [15:0] y2 = r1 + ((9*y)>>4) + ((5*r2)>>4);
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; r1<=0; r2<=0; r3<=0; r4<=0; r5<=0; r6<=0; r7<=0; r8<=0; r9<=0; r10<=0; r11<=0; r12<=0; r13<=0; r14<=0; r15<=0; r16<=0; r17<=0; r18<=0; fb<=0; end
    else begin
      y <= y2;
      r1 <= (25*x) & 16'hFFFF;
      r2 <= (26*x) & 16'hFFFF;
      r3 <= (46*x) & 16'hFFFF;
      r4 <= (49*x) & 16'hFFFF;
      r5 <= (16*x) & 16'hFFFF;
      r6 <= (8*x) & 16'hFFFF;
      r7 <= (15*x) & 16'hFFFF;
      r8 <= (31*x) & 16'hFFFF;
      r9 <= (37*x) & 16'hFFFF;
      r10 <= (52*x) & 16'hFFFF;
      r11 <= (6*x) & 16'hFFFF;
      r12 <= (54*x) & 16'hFFFF;
      r13 <= (60*x) & 16'hFFFF;
      r14 <= (33*x) & 16'hFFFF;
      r15 <= (33*x) & 16'hFFFF;
      r16 <= (62*x) & 16'hFFFF;
      r17 <= (48*x) & 16'hFFFF;
      r18 <= (18*x) & 16'hFFFF;
      fb <= ((9*y)>>4) + ((5*y2)>>4);
    end
  end
endmodule
